import { Alert, Button } from "march/ui"
import { sun, cloud, zap } from "march/icons"

// havanın ruh hâli: düğmeye her basışta uyarının tonu, ikonu ve mesajı birlikte değişir
const MOODS = [
  { tone: "success", icon: sun, title: "Güneşli", text: "Bugün yürüyüş için harika bir gün." },
  { tone: "info", icon: cloud, title: "Bulutlu", text: "Hafif bir hırka yanınızda olsun." },
  { tone: "warn", icon: zap, title: "Fırtına", text: "Akşamüstü gök gürültülü sağanak bekleniyor." },
] as const

export function MoodAlert() {
  let $i = 0
  const mood = () => MOODS[$i % MOODS.length]!
  return <div sx={{ flex: "col", gap: 2 }}>
    {() => <Alert tone={mood().tone} icon={mood().icon} title={mood().title}
      action={<Button size="sm" on:click={() => $i++}>Yarın?</Button>}>{mood().text}</Alert>}
  </div>
}

import { Alert, Button, toast } from "march/ui"
import { shield } from "march/icons"

// bir sitenin çerez bildirimi: yüzen (raised) bildirim, eylemler metnin altında; kapatınca bir daha görünmez
export function CookieNotice() {
  let $choice = ""
  const pick = (c: string) => { $choice = c; toast(c === "all" ? "Tüm çerezler kabul edildi" : "Yalnız gerekli çerezler") }
  return <div sx={{ flex: "col", gap: 2 }}>
    {() => $choice ? <span sx={{ color: "muted" }}>Seçiminiz kaydedildi: {$choice === "all" ? "tümü" : "gerekli olanlar"}</span>
      : <Alert variant="raised" tone="neutral" icon={shield} title="Çerezler" actionPlacement="below"
          dismissable dismissLabel="Bildirimi kapat" onDismiss={() => pick("needed")}
          action={[<Button size="sm" variant="primary" on:click={() => pick("all")}>Tümünü kabul et</Button>,
            <Button size="sm" variant="ghost" on:click={() => pick("needed")}>Yalnız gerekli</Button>]}>
          Deneyiminizi iyileştirmek için çerez kullanıyoruz.
        </Alert>}
  </div>
}

import { test, expect, renderTest } from "march/testing"
import { AlertLab } from "./AlertLab.tsx"

// AlertLab'in testleri: kaydedince Testler sekmesinde çalışır
test("warn ve danger role=alert, diğerleri role=status; role prop'u üstün gelir", () => {
  const s = renderTest(() => <AlertLab />)
  expect(s.find("Ton: danger")?.closest(".m-alert")?.getAttribute("role")).toBe("alert")
  expect(s.find("Ton: info")?.closest(".m-alert")?.getAttribute("role")).toBe("status")
  expect(s.get(".lab-alert")?.getAttribute("role")).toBe("note")
})

test("kapat düğmesi uyarıyı gizler ve onDismiss çağrılır", async () => {
  const s = renderTest(() => <AlertLab />)
  await s.click("Başarı mesajını kapat")
  expect(s.sees("Kapatınca sayaç artar.")).toBe(false)
  expect(s.sees("Kapatılan: 1")).toBe(true)
})

test("action() nesnesi düğme olur ve çalışır", async () => {
  const s = renderTest(() => <AlertLab />)
  await s.click("Kaydet")
  await s.flush()
  expect(s.sees("kaydedilen: 1")).toBe(true)
})

test("partClass parçalara, class köke eklenir; icon={null} ikonu kaldırır", () => {
  const s = renderTest(() => <AlertLab />)
  const lab = s.get(".lab-alert")
  expect(lab?.querySelector(".lab-body")).not.toBe(null)
  expect(lab?.querySelector(".lab-x")).not.toBe(null)
  expect(s.find("İkonsuz")?.closest(".m-alert")?.querySelector(".m-alert-icon")).toBe(null)
})
